-- Synthetic local fixtures only; never apply this file to a hosted database.
CREATE TABLE users(id text PRIMARY KEY, name text NOT NULL, email text, role text NOT NULL, "isActive" boolean NOT NULL DEFAULT true);
INSERT INTO users(id,name,role) VALUES ('owner','Owner','SUPER_ADMIN'),('editor','Editor','LAWYER'),('reviewer','Reviewer','LAWYER'),('reviewer2','Reviewer 2','LAWYER'),('publisher','Publisher','LAWYER'),('agent','Agent','LAWYER'),('admin','Admin','SYSTEM_ADMIN');
UPDATE users SET email=id || '@example.test';
CREATE TABLE legal_systems(id text PRIMARY KEY,name text UNIQUE NOT NULL,classification text,code text UNIQUE,domain text,domain_title text,sort_order integer NOT NULL DEFAULT 0,eli_slug text UNIQUE,"articleCount" integer NOT NULL DEFAULT 0,preamble text,preamble_royal_decree text,preamble_effective_from timestamp,preamble_updated_at timestamp,"createdAt" timestamp NOT NULL DEFAULT now(),"updatedAt" timestamp NOT NULL DEFAULT now());
INSERT INTO legal_systems(id,name,domain) VALUES ('work1','نظام اختبار أول','civil'),('work2','نظام اختبار ثان','civil'),('work3','نظام اختبار ثالث','civil'),('work4','نظام اختبار رابع','criminal');
INSERT INTO legal_systems(id,name,domain) VALUES('work5','نظام اختبار خامس','civil');
CREATE TABLE verification(id text PRIMARY KEY,object_type text NOT NULL,object_id text NOT NULL,verified_status text NOT NULL,evidence_instrument text,evidence_url text,evidence_quote text,method text NOT NULL,verified_by text,verified_at timestamptz NOT NULL DEFAULT now(),supersedes_verification_id text);
CREATE TABLE unit_version(id text PRIMARY KEY,unit_id text NOT NULL,body text NOT NULL,valid_from timestamp NOT NULL,evidence_instrument text,evidence_url text,evidence_quote text,created_at timestamp DEFAULT now());
CREATE TABLE legal_articles(id text PRIMARY KEY,"legalSystemId" text REFERENCES legal_systems(id),"lawName" text NOT NULL,classification text,"articleNumber" integer NOT NULL,title text NOT NULL,content text NOT NULL,chapter text,keywords text[] DEFAULT '{}',"royalDecree" text,"effectiveFrom" timestamp,status text NOT NULL DEFAULT 'سارية',embedding jsonb,search_norm text,"createdAt" timestamp DEFAULT now(),"updatedAt" timestamp DEFAULT now());
INSERT INTO legal_articles(id,"legalSystemId","lawName","articleNumber",title,content) VALUES('unit1','work1','نظام اختبار أول',1,'مادة اختبار','نص المادة الأصلي');
INSERT INTO legal_systems(id,name) VALUES('fixture-companies','نظام الشركات');
INSERT INTO legal_articles(id,"legalSystemId","lawName","articleNumber",title,content) VALUES('fixture-company-article','fixture-companies','نظام الشركات',1,'مادة تجريبية','نص تجريبي لا يمثل التشريع الحقيقي');
CREATE TABLE judicial_cases(id text PRIMARY KEY,"sourceId" integer,"sourcePageId" integer,"decisionNo" text,"caseNo" text,"courtOfAppeal" text,"cityOfAppeal" text,court text,"cityName" text,"decisionDateText" text,"caseDateText" text,"decisionDate" timestamp,"caseDate" timestamp,classification jsonb,"judgmentTitle" text,"judgmentText" text NOT NULL,"appealText" text,"sourceLink" text,source text DEFAULT 'fixture',"reviewStatus" text DEFAULT 'needs_review',"createdAt" timestamp DEFAULT now(),"updatedAt" timestamp DEFAULT now());
INSERT INTO judicial_cases(id,"judgmentText") VALUES('case1','نص قضائي تجريبي');
CREATE TABLE judicial_principles(id text PRIMARY KEY,title text NOT NULL,"principleText" text NOT NULL,"sourceCaseId" text NOT NULL REFERENCES judicial_cases(id),court text,topic text,confidence double precision,"reviewStatus" text NOT NULL DEFAULT 'needs_review',"createdAt" timestamp DEFAULT now(),"updatedAt" timestamp DEFAULT now());
INSERT INTO judicial_principles(id,title,"principleText","sourceCaseId") VALUES('principle1','مبدأ تجريبي','النص التجريبي الأول','case1'),('principle2','مبدأ ثان','النص التجريبي الثاني','case1');
CREATE SCHEMA uqn_fix;
CREATE TABLE uqn_fix.amendment_op(op_id text PRIMARY KEY,target_law_title text,evidence_quote text,source_url text,instrument_no text,confidence text,verbatim_in_source boolean,new_text text);
INSERT INTO uqn_fix.amendment_op VALUES('op1','نظام اختبار أول','دليل التعديل الأول','https://example.test/op1','م/1','rule_exact',true,'نص تعديل تجريبي');
INSERT INTO uqn_fix.amendment_op VALUES('op2','نظام اختبار ثان','دليل التعديل الثاني','https://example.test/op2','م/2','rule_exact',true,'نص تعديل تجريبي'),('op3','نظام اختبار ثالث','دليل التعديل الثالث','https://example.test/op3','م/3','uncertain',false,'نص غير متحقق');
CREATE TABLE uqn_fix.amendment_review(id bigserial PRIMARY KEY,op_id text NOT NULL REFERENCES uqn_fix.amendment_op(op_id),decision text NOT NULL,corrected jsonb,reviewer text NOT NULL,note text,decided_at timestamptz DEFAULT now());
CREATE VIEW uqn_fix.amendment_decision AS SELECT DISTINCT ON(op_id) op_id,decision,corrected,reviewer,decided_at FROM uqn_fix.amendment_review ORDER BY op_id,decided_at DESC,id DESC;
